<script>
// ============================ K-means with merging (main.tex Sections 1–3) ============================
// Same rules as experiments/sim/mutual.html: k-means++ seeding, one Lloyd step per tick, level-synchronous,
// no centroid deleted, root cell = padded bounding box of the points; then mutual closest-first merging.
(() => {
"use strict";
const $ = id => document.getElementById(id);
function rng(seed){ let s = (seed >>> 0) || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; }; }
